-- KAN-264: 억양 학습 발행본 in-gn-2026.10.1 - 코스 17개, 카드 145장 (레벨 1 3개, 레벨 2 4개, 레벨 3 4개, 레벨 4 4개, 레벨 5 2개).
--
-- 이 파일은 손으로 쓰지 않는다 - tools/content/build_intonation_learning.py가 레벨테스트 정의
-- gn-2026.10.1의 VOICE 문항에서 만든다. 대사, scriptKey, 가이드 곡선은 원천 그대로이고, 레벨은
-- 어절 수, 코스는 레벨 안에서 10카드 상한으로 균등 분할이다. 주제, 표준어 원문, 기준 음원은
-- 원천에 없어 전부 null이다 (명세서 §3.17, 2026-10-08 결정).
--
-- 발행 후 불변이다 (§5.4와 같은 규칙). 표준어 원문이나 기준 음원이 채워지면 이 행을 UPDATE하지
-- 않고 새 contentVersion으로 INSERT한다. 활성 전환 행은 없다 - 서버가 발행 시각이 가장 늦은
-- 발행본을 목록과 상세에 쓴다.
